  if(path==='/mcp'&&body?.method==='tools/call'&&body.params?.name?.startsWith('add_'))body.params.arguments={...body.params.arguments,idempotency_key:body.params.arguments?.idempotency_key||'fixture:'+randomBytes(16).toString('hex')};
  if(originHeader)headers.Origin=origin;
  if(auth==='cookie'&&cookie)headers.Cookie=cookie;
  else if(auth==='token')headers.Authorization='Bearer '+machine;
  else if(auth==='fake')headers.Authorization='Bearer cookie-session';
